@pytest.mark.skipif(config.IS_WINDOWS, reason="SIGUSR1 does not exist on Windows")
class TestSendToggle:
    def test_signals_pid_from_file(self, tmp_path):
        pid_file = tmp_path / "dashboard.pid"
        pid_file.write_text("4321", encoding="utf-8")
        with (
            mock.patch.object(config, "PID_FILE", pid_file),
            mock.patch.object(os, "kill") as kill,
        ):
            assert _send_toggle() == EXIT_SUCCESS
        kill.assert_called_once_with(4321, signal.SIGUSR1)

    def test_missing_pid_file_errors(self, tmp_path):
        with mock.patch.object(config, "PID_FILE", tmp_path / "nope.pid"):
            assert _send_toggle() == EXIT_ERROR

    def test_dead_pid_errors(self, tmp_path):
        pid_file = tmp_path / "dashboard.pid"
        pid_file.write_text("4321", encoding="utf-8")
        with (
            mock.patch.object(config, "PID_FILE", pid_file),
            mock.patch.object(os, "kill", side_effect=ProcessLookupError("no such process")),
        ):
            assert _send_toggle() == EXIT_ERROR

    def test_empty_pid_file_errors(self, tmp_path):
        """A lock file created but not yet written must not crash the caller."""
        pid_file = tmp_path / "dashboard.pid"
        pid_file.write_text("", encoding="utf-8")
        with mock.patch.object(config, "PID_FILE", pid_file):
            assert _send_toggle() == EXIT_ERROR

    def test_windows_unsupported(self):
        with mock.patch.object(config, "IS_WINDOWS", True):
            assert _send_toggle() == EXIT_ERROR
